from playwright.sync_api import sync_playwright
errs=[]
def ok(c,m):print(('OK   ' if c else 'FAIL ')+m)
with sync_playwright() as p:
    b=p.chromium.launch();g=b.new_page(viewport={'width':1200,'height':760});g.on('pageerror',lambda x:errs.append(str(x)))
    g.goto('file://'+__import__('os').path.abspath(__import__('os').path.join(__import__('os').path.dirname(__file__),'..','index.html')))
    port=lambda n,o,i:g.locator('.node').nth(n).locator(f'.port[data-o="{o}"][data-p="{i}"]')
    port(0,1,0).click();port(1,0,0).click();port(2,1,0).click();port(1,0,1).click()
    ok(g.evaluate('S.wires.length')==2,'мышью соединяются два провода')
    g.wait_for_timeout(5000);ok(g.evaluate('S.money>0 && S.users>10'),'идут деньги и люди')
    bx=g.locator('.node .t').nth(2).bounding_box();g.mouse.move(bx['x']+40,bx['y']+8);g.mouse.down();g.mouse.move(bx['x']+140,bx['y']+60,steps=5);g.mouse.up()
    ok(g.evaluate('S.nodes[2].x')>90,'блок перетаскивается')
    g.click('#zout');ok(g.evaluate('zoom')==.75,'масштаб')
    g.keyboard.press('Escape');t=g.evaluate('S.t');g.wait_for_timeout(1000);ok(g.evaluate('S.t')==t and g.is_visible('#po'),'Esc останавливает время');g.keyboard.press('Escape')
    g.fill('#addr','отк');ok('энергосбыт' in g.inner_text('#sugg') or 'УКЭн' in g.inner_text('#sugg'),'поиск по первым буквам находит энергосбыт');g.keyboard.press('Enter')
    g.fill('#addr','реест ад');g.keyboard.press('Enter');g.fill('#ip','185.41.7.21');ok('Центр связи' in g.inner_text('#who'),'реестр адресов')
    g.fill('#addr','сквозн');ok('Ничего' in g.inner_text('#sugg'),'база перелётов не находится раньше 60-го дня');g.click('.none');ok(not g.is_visible('#sugg'),'пустые подсказки закрываются нажатием')
    # к 62-му дню
    g.evaluate("()=>{paused=true;while(S.t<61.5*E.DAY){step(1);sum=0;$('so').hidden=true}paused=false}")
    g.click('#marks [data-u="admin.set"]');g.locator('.flt').first.fill('c-7f3a user_418');ok('user_418' in g.inner_text('.tb'),'фильтр журнала');g.fill('#dmq','user_418');ok('администрации' in g.inner_text('#dm'),'переписка второго')
    g.fill('#addr','сквоз');g.keyboard.press('Enter');g.locator('.flt').first.fill('корсаков');ok('возврат' in g.inner_text('.tb'),'в базе есть сданный билет')
    g.locator('.pin').first.click();g.click('#marks [data-u="dosie.set"]');ok('Корсаков' in g.input_value('#notes'),'строка уходит в досье')
    g.click('#marks [data-u="chat.set"]');ok(g.locator('.shot').count()==3,'скриншоты в чате')
    ok(g.evaluate("(()=>{const e=$('p-page');return e.scrollTop+e.clientHeight>=e.scrollHeight-2})()"),'чат открыт на новых сообщениях');g.screenshot(path='/home/claude/g_chat.png')
    g.click('#marks [data-u="otvet.set"]');g.fill('#ans','Корсаков Лев Андреевич');g.click('#send');ok(g.evaluate('UI.answer')is None,'нужно подтверждение');g.click('#send');ok(g.locator('#ans').count()==0,'вторая попытка невозможна')
    ok(g.evaluate('Object.keys(checks).length')>=7,'контрольные точки')
    g.reload();ok(g.evaluate('G.day()')>=62 and g.evaluate('UI.answer')is not None,'сохранение после перезагрузки')
    g.evaluate("()=>{paused=true;while(!ended){step(1);sum=0}$('so').hidden=true}");ok(g.is_visible('#eo') and 'Плохая' in g.inner_text('#eh'),'без 5 млн — плохая концовка')
    g.locator('#ecp button').filter(has_text='День 51').click();ok(g.evaluate('G.day()')==51 and not g.is_visible('#eo') and g.evaluate('UI.answer')is None,'возврат к контрольной точке')
    g.evaluate("()=>{paused=true;UI.answer='лев корсаков';S.users=6e6;S.t=100*E.DAY;finish()}");ok('Обе' in g.inner_text('#eh'),'хорошая концовка')
    g.evaluate("()=>restore(JSON.parse(JSON.stringify(checks[11])))");g.click('#marks [data-u="lenta.set"]');g.screenshot(path='/home/claude/g_feed.png')
    c=b.new_context(viewport={'width':390,'height':760},has_touch=True,is_mobile=True);m=c.new_page();m.on('pageerror',lambda x:errs.append(str(x)));m.goto('file://'+__import__('os').path.abspath(__import__('os').path.join(__import__('os').path.dirname(__file__),'..','index.html')))
    port=lambda n,o,i:m.locator('.node').nth(n).locator(f'.port[data-o="{o}"][data-p="{i}"]')
    port(0,1,0).tap();port(1,0,0).tap();port(2,1,0).tap();port(1,0,1).tap();ok(m.evaluate('S.wires.length')==2,'касаниями соединяются провода')
    r=m.locator('#shop button').first.bounding_box();ok(r is not None and r['y']+r['height']<=760,'на телефоне виден магазин');m.screenshot(path='/home/claude/m_feed.png')
    m.locator('#marks [data-u="admin.set"]').tap();ok(m.evaluate('document.documentElement.scrollWidth')<=390,'на телефоне нет горизонтального сдвига страницы');m.screenshot(path='/home/claude/m_admin.png')
print('ошибки скрипта:',errs)
